test('printed source calculations preserve every relation arrow rather than silently concatenating arithmetic steps',async()=>{
 const observed=JSON.parse(read('tests/fixtures/guidance-translation/calculation-arrow-before.json'))as{sourceClause:string;paintedText:string};const printable=(text:string)=>text.replace(/≤/g,'<=').replace(/≥/g,'>=').replace(/→/g,'->').replace(/[–—]/g,'-');const requireClause=(text:string,clause:string)=>assert.ok(flat(printable(text)).includes(flat(printable(clause))),'the complete sourced calculation must retain every arithmetic relation');assert.throws(()=>requireClause(observed.paintedText,observed.sourceClause),'the actual failed extraction must fail even though all digits and units survived');const row=before.rows.find(row=>row.products?.trees.length===103)!,tree=row.products!.trees.find(tree=>tree.harvest.speciesId==='prunus-persica')!,products={...row.products!,trees:[tree],animals:[]};
 for(const language of['en',...CROP_EXPORT_DRAFT_LANGUAGES]){const guide=buildProductionGuide(row.survey,row.plantings,[],10,products,language),note=guide.foodForest?.[0].lines.find(line=>line.includes('→'));assert.ok(note,'the original source calculation must be exercised');const input={...inputs[0].input,now:new Date(inputs[0].input.now),meta:{...inputs[0].input.meta,language},productionGuide:guide,poultryGuidance:undefined},snapshot: string=JSON.stringify(input),doc=new jsPDF({unit:'pt',format:'a4'}),font=await registerReportPdfFont(doc),painted:string[]=[];const text=doc.text.bind(doc);doc.text=((...args:unknown[])=>{painted.push((Array.isArray(args[0])?args[0].map(String):[String(args[0])]).join(' '));return(text as(...args:unknown[])=>jsPDF)(...args);})as typeof doc.text;drawCropPlanPages(doc,input,false,{language,font});const body=painted.join(' ');requireClause(body,note);assert.ok(!body.includes('→'),'the font must receive the supported relation token');assert.equal(JSON.stringify(input),snapshot,'source note and source figures must never be rewritten while painting');}
});

test('native crop-choice heading and full caution stay with their first card after long reference qualifiers',async()=>{
 const fixture=JSON.parse(read('tests/fixtures/guidance-translation/section-intro-before.json'))as{input:Omit<CropPlanPdfInput,'now'>&{now:string};firstEntry:{title:string;lines:string[]};beforePages:string[]};const language=fixture.input.meta.language!,clauses=[cropExportText('Crop varieties to check locally',language),cropExportText('Keep the named variety you actually choose. Research shortlists need confirmation for your local season, water and ground.',language),fixture.firstEntry.title,fixture.firstEntry.lines[0]];const requireStart=(pages:string[])=>assert.ok(pages.some(page=>clauses.every(clause=>flat(page).includes(flat(clause)))),'a section introduction must not leave its first ordinary card on the next page');assert.throws(()=>requireStart(fixture.beforePages),'the actual heading/intro orphan must fail even though its first card was printed later');
 const input={...fixture.input,now:new Date(fixture.input.now)},snapshot: string=JSON.stringify(input),doc=new jsPDF({unit:'pt',format:'a4'}),font=await registerReportPdfFont(doc),pages=new Map<number,string[]>();const text=doc.text.bind(doc);doc.text=((...args:unknown[])=>{const page=doc.getCurrentPageInfo().pageNumber,lines=(Array.isArray(args[0])?args[0].map(String):[String(args[0])]).join(' ');pages.set(page,[...(pages.get(page)??[]),lines]);return(text as(...args:unknown[])=>jsPDF)(...args);})as typeof doc.text;drawCropPlanPages(doc,input,false,{language,font});requireStart([...pages.values()].map(lines=>lines.join(' ')));assert.equal(JSON.stringify(input),snapshot,'grouping must not edit the original plan or source cautions');
});

test('wild-fruit drafts bind whole immutable fields and keep the existing calendar month associations',()=>{
 const packet=JSON.parse(read('docs/translation/four-language-completion/authored-product-batch04-drafts.json'))as{status:string;sourceCount:number;rows:Array<Record<string,string>>;sourceBindings:Array<{english:string;identities:string[]}>};assert.match(packet.status,/Unreviewed/);assert.equal(packet.sourceCount,17);assert.equal(packet.rows.length,packet.sourceBindings.length);const context=before.rows.find(row=>row.products?.trees.length===103)!.products!;
 for(const[index,row]of packet.rows.entries()){
  const binding=packet.sourceBindings[index];assert.equal(row.english,binding.english);
  for(const id of binding.identities){const group=context.trees.find(tree=>tree.harvest.speciesId===id);assert.ok(group,'every binding must belong to an original captured species');const h=group.harvest,profile=PRODUCT_PROFILES[id]??h.productionGuidance;const originals=[profile?.products??h.product,...(profile?.care??[]),...(profile?.purchase??[]),...(h.supplementaryReferences??[]).flatMap(reference=>[reference.title,reference.note])];assert.ok(originals.includes(row.english),'a display draft cannot replace a source field with a new agronomic claim');}
  for(const language of CROP_EXPORT_DRAFT_LANGUAGES){assert.equal(productGuideText(row.english,language),row[language]);assert.notEqual(row[language],row.english);assert.deepEqual(figures(row[language]),figures(row.english));assert.equal(productGuideText(row.english),row.english);assert.equal(productGuideText(row.english,'xx'),row.english);for(const identity of['SANBI','Ehretia','Euclea undulata'])if(row.english.includes(identity))assert.ok(row[language].includes(identity),'the original institution or plant identity must remain explicit');}
 }
 for(const language of CROP_EXPORT_DRAFT_LANGUAGES)for(const[index,from,to]of[[3,1,5],[5,11,1],[13,2,5]])assert.ok(packet.rows[index][language].includes(`${recordsMonthLong(language,from)}–${recordsMonthLong(language,to)}`),'fruiting and ripening ranges must keep the source start/end order');
 for(const language of CROP_EXPORT_DRAFT_LANGUAGES)assert.ok(packet.rows[16][language].includes(recordsMonthLong(language,2)),'appearance from February cannot silently become a different month');
});

test('actual wild-fruit guides retain the whole ripe-picking uncertainty and plant-sex checks without changing source calendars',()=>{
 const packet=JSON.parse(read('docs/translation/four-language-completion/authored-product-batch04-drafts.json'))as{rows:Array<Record<string,string>>;representativeSpecies:string[]};const row=before.rows.find(row=>row.id==='trees-subtropical-coast')!,all=row.products!,ids=new Set(packet.representativeSpecies),context={...all,trees:all.trees.filter(tree=>ids.has(tree.harvest.speciesId)),animals:[]};assert.equal(context.trees.length,ids.size);const snapshot: string=JSON.stringify(context),original=buildProductGuidance(context,[],row.survey?.productionConditions);assert.deepEqual(buildProductGuidance(context,[],row.survey?.productionConditions,'xx'),original);
 for(const language of CROP_EXPORT_DRAFT_LANGUAGES){const native=buildProductGuidance(context,[],row.survey?.productionConditions,language);native.foodForest.forEach((item,index)=>{assert.equal(item.title,original.foodForest[index].title);assert.deepEqual(item.sources,original.foodForest[index].sources);assert.deepEqual(item.expectedSeason?.months,original.foodForest[index].expectedSeason?.months);assert.deepEqual(figures(item.lines.join(' ')),figures(original.foodForest[index].lines.join(' ')));});const text=native.foodForest.flatMap(item=>item.lines).join(' ');for(const source of packet.rows)assert.ok(flat(text).includes(flat(source[language])),'each full source distinction must reach the actual guide: '+source.english);
  const requireCautions=(body:string)=>{for(const index of[2,3,5,7,8,10,11,13,15,16])assert.ok(flat(body).includes(flat(packet.rows[index][language])),'native headings or product labels alone cannot replace complete source conditions');};requireCautions(text);
  // The original uncertainty and reproductive checks carry practical meaning;
  // a guide retaining the product/flowering heading must still reject their loss.
  for(const index of[3,5,7,16]){const removed=text.split(packet.rows[index][language]).join('');assert.ok(removed.includes(packet.rows[index===5?4:0][language]));assert.throws(()=>requireCautions(removed));}
  const unassigned=context.trees.findIndex(tree=>tree.harvest.speciesId==='dovyalis-afra');assert.equal(native.foodForest[unassigned].expectedSeason,undefined,'flowering/fruit-development observations cannot acquire a ripe-picking calendar');assert.equal(JSON.stringify(context),snapshot,'native display cannot write back into source or stored context');
 }
});

test('crop research drafts retain immutable whole fields, ordered figures and original trial identities',()=>{
 const packet=JSON.parse(read('docs/translation/four-language-completion/authored-product-batch05-drafts.json'))as{status:string;sourceCount:number;rows:Array<Record<string,string>>;sourceBindings:Array<{english:string;identities:string[]}>};assert.match(packet.status,/IN PROGRESS.*Unreviewed/);assert.equal(packet.sourceCount,48);assert.equal(packet.rows.length,packet.sourceBindings.length);const context=before.rows.find(row=>row.products?.trees.length===103)!.products!,numbers=(s:string)=>s.match(/\d+(?:[.,]\d+)?/g)??[];
 for(const[index,row]of packet.rows.entries()){
  assert.equal(row.english,packet.sourceBindings[index].english);
  for(const id of packet.sourceBindings[index].identities){const group=context.trees.find(tree=>tree.harvest.speciesId===id);assert.ok(group,'translation must bind to an existing captured species');const h=group.harvest,p=PRODUCT_PROFILES[id]??h.productionGuidance;assert.ok([p?.products??h.product,...(p?.care??[]),...(p?.purchase??[]),...(h.supplementaryReferences??[]).flatMap(ref=>[ref.title,ref.note])].includes(row.english),'a draft cannot supply a new source claim');}
  for(const language of CROP_EXPORT_DRAFT_LANGUAGES){assert.equal(productGuideText(row.english,language),row[language]);assert.notEqual(row[language],row.english);assert.deepEqual(numbers(row[language]),numbers(row.english),'source figures retain their sequence, decimals and leading zeros');for(const identity of['ARC Infruitec Citrusdal','Kadota','White Genoa','Calimyrna','Tena','Black Mission','Conadria','Ephesus','Excell','Deanna','Platyscapa desertorum','Ficus carica','Ficus sur','SANBI','Grewia flava','Grewia robusta','Grevillea robusta','Dalmada','Polokwane','CPI 52552','CPI 60795','CQ 3620','Rongai black','HLH Mauritius','Red McLean','Fay Zee Siu','Mandellup','Lila-Baer','Tanjil','Riversdale','Swellendam','Tygerhoek','kg/tree/year','kg/tree','kg/ha','t/ha'])if(row.english.includes(identity))assert.ok(row[language].includes(identity),'source identity and dimension must remain traceable: '+identity);assert.equal(productGuideText(row.english),row.english);assert.equal(productGuideText(row.english,'xx'),row.english);}
 }
 for(const language of CROP_EXPORT_DRAFT_LANGUAGES){for(const[index,start,end]of[[20,9,3],[23,10,3],[27,8,12],[43,4,5]])assert.ok(packet.rows[index][language].includes(`${recordsMonthLong(language,start)}–${recordsMonthLong(language,end)}`),'source flowering/production/planting month ranges retain their order');for(const[index,day,month]of[[33,10,12],[41,15,4],[41,12,5],[41,24,4],[41,29,10]])assert.ok(packet.rows[index][language].includes(`${day} ${recordsMonthLong(language,month)}`),'an observed trial date cannot become a current planting recommendation');}
});

test('actual crop research guides keep food holds, paired trial yields and preparation limits with their citations',()=>{
 const packet=JSON.parse(read('docs/translation/four-language-completion/authored-product-batch05-drafts.json'))as{rows:Array<Record<string,string>>;representativeSpecies:string[]};const source=before.rows.find(row=>row.id==='trees-subtropical-coast')!,ids=new Set(packet.representativeSpecies),context={...source.products!,trees:source.products!.trees.filter(tree=>ids.has(tree.harvest.speciesId)),animals:[]};assert.equal(context.trees.length,ids.size);const original=buildProductGuidance(context,[],source.survey?.productionConditions),snapshot: string=JSON.stringify(context);assert.deepEqual(buildProductGuidance(context,[],source.survey?.productionConditions,'xx'),original);
 for(const language of CROP_EXPORT_DRAFT_LANGUAGES){const native=buildProductGuidance(context,[],source.survey?.productionConditions,language);native.foodForest.forEach((item,i)=>{assert.equal(item.title,original.foodForest[i].title);assert.deepEqual(item.sources,original.foodForest[i].sources);assert.deepEqual(item.expectedSeason?.months,original.foodForest[i].expectedSeason?.months);assert.deepEqual(figures(item.lines.join(' ')),figures(original.foodForest[i].lines.join(' ')));});const text=native.foodForest.flatMap(item=>item.lines).join(' ');const requireWholeConditions=(body:string)=>{for(const row of packet.rows)assert.ok(flat(body).includes(flat(row[language])),'every full source field, including its qualifier, must reach the guide: '+row.english);};requireWholeConditions(text);
  // Product names, titles and the remaining source text survive these failures:
  // none can substitute for the human-food hold, separate forage amount, trial
  // limitation, harvest-loss distinction or absence of a home debittering method.
  for(const index of[5,7,15,30,33,35,41,45,47]){const changed=text.split(packet.rows[index][language]).join('');assert.ok(changed.includes(packet.rows[index===15?14:index===47?46:0][language]));assert.throws(()=>requireWholeConditions(changed));}
  const trial=packet.rows[33][language],swap=trial.replace('576.2','__grain__').replace('570.5','576.2').replace('__grain__','570.5');assert.deepEqual(figures(swap),figures(trial),'swapping trial outputs would evade a sorted-number-only check');assert.throws(()=>requireWholeConditions(text.replace(trial,swap)),'accessions must retain their own paired output');assert.equal(JSON.stringify(context),snapshot,'display must not mutate source product records');
 }
});
